# Define the calculation for Q when (a, b, c) = (0, 0, 0)
# Q = |x+y| + |y+z| + |z+x|. Since x, y, z >= 0, Q = 2(x+y+z).

collisions = {}
max_sum = 27 # Max value for x+y+z is 9+9+9 = 27

for x in range(10):
    for y in range(10):
        for z in range(10):
            S = x + y + z
            Q = 2 * S

            # Store the triple associated with Q
            if Q not in collisions:
                collisions[Q] = []

            collisions[Q].append((x, y, z))

# Identify collisions (where length of the list is > 1)
collision_sets = {Q: triples for Q, triples in collisions.items() if len(triples) > 1}

print(f"Total number of unique Q values found: {len(collisions)}")
print(f"Number of colliding Q values: {len(collision_sets)}")

if collision_sets:
    print("\n--- Examples of Collisions ---")
    # Print the first few collision sets for inspection
    count = 0
    for Q, triples in collision_sets.items():
        if count < 5:
            print(f"Q = {Q} (Sum = {Q//2}): Triples include {triples[:3]}... ({len(triples)} total)")
            count += 1
        else:
            break
else:
    print("\nNo collisions found.")

